style.css:
@-moz-document domain("google.com"), domain("google.cl") {
/* 1. FONDO DE MALLA (Asegurando Transparencia Total) */
    html, body, #gsr, .islmp, #main, #cnt, .islrc, #islrg {
        background-color: #030712 !important;
        background-image: 
            radial-gradient(at 10% 20%, rgba(56, 189, 248, 0.15) 0px, transparent 50%),
            radial-gradient(at 90% 10%, rgba(168, 85, 247, 0.15) 0px, transparent 50%),
            radial-gradient(at 50% 50%, rgba(30, 58, 138, 0.1) 0px, transparent 80%) !important;
        background-attachment: fixed !important;
        background-color: transparent !important;
    }

    /* 2. STICKY HEADER CON BLUR (La barra superior) */
    #searchform, .sfbg, .sheader, #hdtb, .SaneHe, .K73S9e {
        background: rgba(15, 23, 42, 0.4) !important;
        backdrop-filter: blur(25px) saturate(180%) !important;
        -webkit-backdrop-filter: blur(25px) saturate(180%) !important;
        border-bottom: 1px solid rgba(255, 255, 255, 0.1) !important;
    }

    /* 3. BARRA DE BÚSQUEDA (Animación Pro Refinada) */
    .RNNXGb {
        background: rgba(255, 255, 255, 0.05) !important;
        backdrop-filter: blur(20px) !important;
        border: 1px solid rgba(255, 255, 255, 0.15) !important;
        border-radius: 28px !important;
        transition: all 0.3s cubic-bezier(0.4, 0, 0.2, 1) !important;
    }

    .RNNXGb:focus-within {
        background: rgba(255, 255, 255, 0.12) !important;
        transform: scale(1.01);
        border-color: rgba(255, 255, 255, 0.3) !important;
        box-shadow: 0 10px 40px rgba(0, 0, 0, 0.5) !important;
    }

    /* 4. BURBUJAS DE FILTROS (Limpieza y Estilo) */
    .hdtb-mitem a, .hdtb-mitem span, .nS4Vae, .rQ7Kae {
        background: rgba(60, 64, 67, 0.8) !important;
        color: #e8eaed !important;
        padding: 8px 18px !important;
        border-radius: 50px !important;
        border: 1px solid rgba(255, 255, 255, 0.08) !important;
        transition: transform 0.2s ease !important;
    }

    /* Burbuja Activa */
    .hdtb-mitem.hdtb-msel a, .hdtb-msel, [aria-current="page"] {
        background: #ffffff !important;
        color: #1a1b1e !important;
        box-shadow: 0 0 15px rgba(255, 255, 255, 0.2) !important;
        border: none !important;
    }

    /* Animación de pulsación solo en clic */
    .hdtb-mitem a:active, .gNO89b:active {
        transform: scale(0.94);
    }

    /* 5. GOOGLE IMÁGENES (Corrección de Fondo Oscuro) */
    /* Quitamos el negro sólido de las miniaturas y el contenedor */
    .islrc, .islmp, .m68S6, .T7S7Vb, .hide-focus-ring, .v47S0e, .e6On6b {
        background: transparent !important;
    }

    /* Miniaturas con efecto cristal suave */
    .isv-r {
        background: rgba(255, 255, 255, 0.02) !important;
        backdrop-filter: blur(5px) !important;
        border-radius: 12px !important;
        border: 1px solid rgba(255, 255, 255, 0.05) !important;
        transition: transform 0.3s ease !important;
    }
    
    .isv-r:hover {
        transform: scale(1.03);
        background: rgba(255, 255, 255, 0.08) !important;
    }

    /* Panel lateral de vista previa de imagen */
    .hSbwV, .X309Ef, .decoded {
        background: rgba(15, 23, 42, 0.7) !important;
        backdrop-filter: blur(30px) !important;
        border-left: 1px solid rgba(255, 255, 255, 0.1) !important;
    }

    /* 6. TRANSPARENCIA GENERAL (Forzado Extremo) */
    #main, #cnt, #rcnt, #center_col, #search, .gLFyf, #footcnt, .fbar, .gb_Ra, 
    .sfbg, .header-wrapper, .SaneHe, .L3eUgb, .o3j99, .background, .G0pUae, 
    .main, .c93Gbe, .K73S9e, .A8706b, .LX3S1e, .m68S6, .T7S7Vb, .IUO97e, .Lj9nQe, .t9S96 {
        background: transparent !important;
        background-color: transparent !important;
        border: none !important;
    }

    /* 7. TEXTO */
    h3, .LC20lb { color: #ffffff !important; }
    .VwiC3b, span, a, cite, em, .Mg70ce { color: #cbd5e1 !important; }
    a:link { color: #60a5fa !important; }

    /* Ocultar elementos basura */
    .yfB6nd, .g:empty { display: none !important; }
}
